export function atracoesPrecosDoPais(code) {
  const itens = (code && ATRACOES_PRECOS[code]) || [];
  // Aplica correções da auditoria (override por 'CODE::nome'), se houver.
  return itens.map((it) => {
    const ov = ATRACOES_PRECOS_OVERRIDE[`${code}::${it.nome}`];
    return ov ? { ...it, ...ov } : it;
  });
}
